+      assert.throws(() => packContext([section('good'), { ...section('bad'), [key]: value }], 0), Error);
+    }
+    const missing = section('missing');
+    delete missing[key];
+    assert.throws(() => packContext([missing], 0), Error);
+  }
+  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
+});
+
+test('required order, priority ties, skip and original omission order', () => {
+  const input = Object.freeze([
+    section('low-large', 'x'.repeat(100), 0),
+    section('first', '', 2),
+    section('required-a', '', 0, true),
+    section('high-large', 'x'.repeat(100), 100),
+    section('second', '', 2),
+    section('required-b', '', 99, true),
+    section('third', '', 1),
+  ].map(Object.freeze));
+  const text = [input[2], input[5], input[1], input[4]].map(frame).join('');
+  const bytes = Buffer.byteLength(text);
+  assert.deepEqual(packContext(input, bytes), {
+    text, bytes,
+    included: ['required-a', 'required-b', 'first', 'second'],
+    omitted: ['low-large', 'high-large', 'third'],
+  });
+  const requiredBytes = Buffer.byteLength(frame(input[2]) + frame(input[5]));
+  assert.throws(() => packContext(input, requiredBytes - 1), Error);
+  assert.deepEqual(packContext(input, requiredBytes).included, ['required-a', 'required-b']);
+});
+
+test('IDs and text preserve escaping, whitespace, Unicode and exact bytes', () => {
+  const input = ['__proto__', 'A', 'a', ' ', '雪\n\u0000"\\', '\ud800']
+    .map(id => ({ ...section(id, ' \r\n雪é😀\u0000\ud800\n '), ignored: true }));
+  const text = input.map(frame).join('');
+  const bytes = Buffer.byteLength(text, 'utf8');
+  assert.deepEqual(packContext(input, bytes), {
+    text, bytes, included: input.map(s => s.id), omitted: [],
+  });
+  assert.equal(packContext(input, Number.MAX_SAFE_INTEGER).bytes, bytes);
+  assert.deepEqual(packContext(input, 0).omitted, input.map(s => s.id));
+});
+
+test('CLI success, errors and import isolation', () => {
+  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
+  try {
+    const file = join(directory, 'input.json');
+    const input = { sections: [section('雪', 'é')], maxBytes: 100, ignored: true };
+    writeFileSync(file, JSON.stringify(input));
+    const success = run([cli, file]);
+    assert.equal(success.status, 0);
+    assert.equal(success.stderr, '');
+    assert.equal(success.stdout, JSON.stringify(packContext(input.sections, input.maxBytes)) + '\n');
+
+    for (const args of [[cli], [cli, file, 'extra'], [cli, join(directory, 'missing.json')]]) {
+      const result = run(args);
+      assert.equal(result.status, 2);
+      assert.equal(result.stdout, '');
+      assert.ok(result.stderr.length > 0);
+    }
+    for (const contents of ['{', 'null', '[]', '{}',
+      JSON.stringify({ sections: [section('r', '', 0, true)], maxBytes: 0 }),
+      JSON.stringify({ sections: [section('bad', '', -1)], maxBytes: 0 })]) {
+      writeFileSync(file, contents);
+      const result = run([cli, file]);
+      assert.equal(result.status, 2);
+      assert.equal(result.stdout, '');
+      assert.ok(result.stderr.length > 0);
+    }
+    const imported = run(['--input-type=module', '-e', `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)}`]);
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(directory, { recursive: true, force: true });
+  }
+});

